    @TempDir Path temporary;
    Map<String,Object> object(Path path)throws IOException{return GraphJson.object(GraphJson.read(Files.readString(path),new GraphJson.Limits(8388608,64,8388608)));}
    ContentHandle handle(Object value){var row=GraphJson.object(value);return new ContentHandle(new ContentDigest(GraphJson.string(row.get("digest"))),((BigDecimal)row.get("size")).longValueExact());}
    ContentHandle put(StreamingContentStore store,Path path)throws IOException{try(var input=Files.newInputStream(path,LinkOption.NOFOLLOW_LINKS)){return store.put(input,()->false);}}
    ContentHandle put(StreamingContentStore store,Object value)throws IOException{return store.put(new ByteArrayInputStream(CanonicalJson.write(value).getBytes(StandardCharsets.UTF_8)),()->false);}
    LanguageSemanticRequest sibling(LanguageSemanticRequest request,String module,SemanticTables tables)throws IOException{
        var provisional=new LanguageSemanticRequest(request.context(),request.inventory(),request.root(),module,request.sourceSet(),request.variant(),request.language(),request.dialect(),request.documents(),request.census(),request.resolution(),request.provider(),request.tool(),request.policy(),request.workPolicy());var scoped=new EnumMap<SemanticTables.Kind,SemanticTables.Table>(SemanticTables.Kind.class);
        for(var table:List.of(request.documents(),request.census())){var rows=new ArrayList<SemanticTables.Row>();try(var reader=tables.open(table,()->false)){SemanticTables.Row row;while((row=reader.next())!=null)rows.add(new SemanticTables.Row(row.kind(),row.key(),provisional.scope(),row.fields()));}scoped.put(table.kind(),tables.write(table.kind(),rows.iterator(),()->false));}
        return new LanguageSemanticRequest(provisional.context(),provisional.inventory(),provisional.root(),module,provisional.sourceSet(),provisional.variant(),provisional.language(),provisional.dialect(),scoped.get(SemanticTables.Kind.DOCUMENT),scoped.get(SemanticTables.Kind.CENSUS),provisional.resolution(),provisional.provider(),provisional.tool(),provisional.policy(),provisional.workPolicy());
    }
    SemanticTables.Table sourceInventory(StreamingContentStore store,SemanticTables tables,ContentDigest inventory,Map<String,String> sources)throws IOException{
        var rows=new ArrayList<SemanticTables.Row>();for(var source:sources.entrySet()){var path=LogicalPath.utf8(source.getKey());var bytes=store.put(new ByteArrayInputStream(source.getValue().getBytes(StandardCharsets.UTF_8)),()->false);rows.add(new SemanticTables.Row(SemanticTables.Kind.DOCUMENT,path.key(),inventory,Map.of("rawPath",path.rawBase64(),"kind","FILE","population","MAIN","disposition","ACQUIRED","content",bytes)));}
        return tables.write(SemanticTables.Kind.DOCUMENT,rows.stream().sorted(Comparator.comparing(SemanticTables.Row::key)).iterator(),()->false);
    }
    SemanticContextCoordinator.RootCensus rootCensus(SemanticContextCoordinator.Plan plan,ContentHandle prepared,StreamingContentStore store,SemanticTables tables,Map<String,LanguageSemanticRequest> selected)throws IOException{
        var sources=new ArrayList<SemanticTables.Row>();try(var reader=tables.open(plan.inventory().entries(),()->false)){SemanticTables.Row row;while((row=reader.next())!=null)sources.add(new SemanticTables.Row(SemanticTables.Kind.CENSUS,row.key(),plan.identity(),Map.of("entry",row.identity(),"disposition","REQUIRED","reason","AUTHORED_NATIVE_INPUT_SET","evidence",prepared)));}
        var contexts=new ArrayList<SemanticTables.Row>();var memberships=new ArrayList<SemanticTables.Row>();for(var entry:selected.entrySet()){
            contexts.add(new SemanticTables.Row(SemanticTables.Kind.CONTEXT,entry.getKey(),plan.identity(),Map.of("disposition","SELECTED","request",entry.getValue().identity(),"reason","AUTHORED_NATIVE_CONTEXT_PLAN","evidence",prepared)));
            try(var reader=tables.open(entry.getValue().documents(),()->false)){SemanticTables.Row doc;while((doc=reader.next())!=null)memberships.add(new SemanticTables.Row(SemanticTables.Kind.DOCUMENT,SemanticRootCensus.documentKey(entry.getKey(),doc.key()),plan.identity(),Map.of("context",entry.getKey(),"document",doc.key(),"documentIdentity",doc.identity(),"origin","INVENTORY","source",LogicalPath.utf8(doc.key()).key(),"content",doc.fields().get("content"),"lineage",prepared)));}
        }
        var input=new SemanticRootCensus.Input(tables.write(SemanticTables.Kind.CENSUS,sources.iterator(),()->false),tables.write(SemanticTables.Kind.CONTEXT,contexts.stream().sorted(Comparator.comparing(SemanticTables.Row::key)).iterator(),()->false),tables.write(SemanticTables.Kind.DOCUMENT,memberships.stream().sorted(Comparator.comparing(SemanticTables.Row::key)).iterator(),()->false),ContentDigest.sha256Utf8("authored-native-membership-validator:m8.4-v1"));
        return new SemanticContextCoordinator.RootCensus(input,()->new SqliteSemanticCensusIndex(temporary.resolve("root-index-"+UUID.randomUUID()+".sqlite"),65536),Optional.empty());
    }
